package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.node.ObjectNode;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Structural/adversarial tests only; not evidence of an issued approval or a successful physical write. */
class TaskNodeProducerSchemaTest {
 private final TaskNodeProducerSchema schema=new TaskNodeProducerSchema();
 TaskNodeProducerSchemaTest()throws Exception{}
 static String id(int n){return String.format("00000000-0000-4000-8000-%012d",n);}
 ObjectNode author()throws Exception{
  var n=(ObjectNode)schema.read("{}");n.put("schema_version","1.0.0");int i=1;
  for(String f:List.of("project_id","task_id","task_revision","plan_revision","template_version","scope_snapshot","release_id","original_rule_id","budget_revision"))n.put(f,id(i++));
  for(String f:List.of("task_input_sha256","plan_sha256","template_sha256","source_manifest_sha256","publication_approval_sha256","original_rule_sha256","original_approval_sha256"))n.put(f,"a".repeat(64));
  for(String f:List.of("role_version","execution_policy","enterprise_budget_basis"))n.putObject(f).put("version_id",id(i++)).put("content_sha256","b".repeat(64));
  for(String f:List.of("maximum_bytes","maximum_artifacts","maximum_tokens","maximum_calls"))n.put(f,"10");
  n.put("maximum_amount","1.25").put("currency","USD").put("valid_from","2026-10-20T00:00:00Z").put("valid_until","2026-10-21T00:00:00Z")
   .put("classification","INTERNAL").put("expected_revision","0").put("reason","Propose bounded N02 production only.");
  n.putArray("question_ids").add(id(50));n.putArray("artifact_kinds").add("TASK_NODE_INPUT");n.putArray("operations").add("NODE_PRODUCE");return n;
 }
 @Test void closedVersionedPreRunContractAcceptsNoRunIdentity()throws Exception{var a=author();assertNotNull(schema.validate("InputAuthor",a));a.put("run_id",id(60));assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));}
 @Test void unknownFieldsAndUnknownKindsFail()throws Exception{var a=author();a.put("automatic_approval",true);assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));var b=author();b.withArray("artifact_kinds").add("ANY_FUTURE_ARTIFACT");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",b));}
 @Test void sourceAndModelOperationsCannotBeSmuggled()throws Exception{for(String op:List.of("artifact.read","model.send","source.read","REGISTERED_ARTIFACT")){var a=author();a.withArray("operations").add(op);assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));}}
 @Test void duplicateQuestionsAndReversedValidityFail()throws Exception{var a=author();a.withArray("question_ids").add(id(50));assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));var b=author();b.put("valid_until","2026-10-19T00:00:00Z");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",b));}
 @Test void overflowAndUnboundedArtifactCountFail()throws Exception{var a=author();a.put("maximum_bytes","18446744073709551616");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));var b=author();b.put("maximum_artifacts","1025");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",b));}
 @Test void hostConsumeNeedsItsOwnExplicitOperationAndExactKind()throws Exception{var a=author();assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT","1","HOST_INPUT_CONSUME"));a.withArray("operations").add("HOST_INPUT_CONSUME");assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT","10","HOST_INPUT_CONSUME"));assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"STEP_ENVELOPE","1","HOST_INPUT_CONSUME"));}
 @Test void predecessorReadIsSeparateFromInputReadAndRequiresEvidenceKind()throws Exception{var a=author();a.withArray("artifact_kinds").add("EVIDENCE_BUNDLE");a.withArray("operations").add("HOST_INPUT_CONSUME");assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"EVIDENCE_BUNDLE","1","HOST_PREDECESSOR_CONSUME"));a.withArray("operations").add("HOST_PREDECESSOR_CONSUME");assertNotNull(schema.validate("InputAuthor",a));assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"EVIDENCE_BUNDLE","1","HOST_PREDECESSOR_CONSUME"));assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT","1","HOST_PREDECESSOR_CONSUME"));assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"EVIDENCE_BUNDLE","1","HOST_INPUT_CONSUME"));}
 @Test void sessionExportRequiresExplicitKindAndNeverImpliesRead()throws Exception{var a=author();assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"SESSION_EXPORT","1","NODE_PRODUCE"));a.withArray("artifact_kinds").add("SESSION_EXPORT");assertNotNull(schema.validate("InputAuthor",a));assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"SESSION_EXPORT","1","NODE_PRODUCE"));a.withArray("operations").add("HOST_PREDECESSOR_CONSUME");assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"SESSION_EXPORT","1","HOST_PREDECESSOR_CONSUME"));}
 @Test void byteBoundsArePositiveAndInclusive()throws Exception{var a=author();assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT","10","NODE_PRODUCE"));for(String size:List.of("0","11","18446744073709551616"))assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT",size,"NODE_PRODUCE"));}
 @Test void independentApprovalAndTerminalDisableAreMandatory(){assertThrows(RuntimeException.class,()->TaskNodeProducerService.requireDecision("DRAFT","APPROVE",id(1),id(1)));assertDoesNotThrow(()->TaskNodeProducerService.requireDecision("DRAFT","APPROVE",id(1),id(2)));assertThrows(RuntimeException.class,()->TaskNodeProducerService.requireDecision("DISABLED","APPROVE",id(1),id(2)));}
 @Test void duplicateJsonAndInvalidUtf8Fail()throws Exception{assertThrows(RuntimeException.class,()->schema.request("InputAuthor","{\"schema_version\":\"1.0.0\",\"schema_version\":\"1.0.0\"}".getBytes(StandardCharsets.UTF_8)));assertThrows(RuntimeException.class,()->schema.request("InputAuthor",new byte[]{(byte)0xc3,0x28}));}
 @Test void leasedProductionAcceptsOnlyPrivateHostProofs()throws Exception{assertNotNull(TaskNodeProducerAuthority.LeasedProduction.class.getMethod("requireProduction",TaskProfessionalRuntimeService.Envelope.class));assertNotNull(TaskNodeProducerAuthority.LeasedProduction.class.getMethod("requireProduction",TaskResearchExecutionService.Produced.class));assertThrows(NoSuchMethodException.class,()->TaskNodeProducerAuthority.LeasedProduction.class.getMethod("requireProduction",String.class,byte[].class));}
 @Test void proofsHaveNoPublicConstructor(){for(var c:TaskNodeProducerAuthority.Verified.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));for(var c:TaskNodeProducerAuthority.LeasedProduction.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));for(var c:TaskNodeProducerOriginalAuthority.Verified.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));}
 @Test void envelopeReadRequiresSeparateExplicitOperation()throws Exception{var a=author();a.withArray("artifact_kinds").add("STEP_ENVELOPE");a.withArray("operations").add("HOST_INPUT_CONSUME");assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"STEP_ENVELOPE","1","HOST_ENVELOPE_CONSUME"));a.withArray("operations").add("HOST_ENVELOPE_CONSUME");assertNotNull(schema.validate("InputAuthor",a));assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"STEP_ENVELOPE","1","HOST_ENVELOPE_CONSUME"));assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_NODE_INPUT","1","HOST_ENVELOPE_CONSUME"));}
 @Test void exactInputKindDoesNotInheritAnyHostRead()throws Exception{var a=author();assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_EXACT_INPUT","1","NODE_PRODUCE"));a.withArray("artifact_kinds").add("TASK_EXACT_INPUT");assertNotNull(schema.validate("InputAuthor",a));assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,"TASK_EXACT_INPUT","1","NODE_PRODUCE"));for(String op:java.util.List.of("HOST_INPUT_CONSUME","HOST_PREDECESSOR_CONSUME","HOST_ENVELOPE_CONSUME")){a.withArray("operations").add(op);assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,"TASK_EXACT_INPUT","1",op));}}
 @Test void invocationOutputsRequireExplicitKindsAndNeverInheritHostRead()throws Exception{
  for(String kind:java.util.List.of("MODEL_RESULT","PROVIDER_CAPTURE")){
   var a=author();assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,kind,"1","NODE_PRODUCE"));
   a.withArray("artifact_kinds").add(kind);assertNotNull(schema.validate("InputAuthor",a));
   assertDoesNotThrow(()->TaskNodeProducerAuthority.requireBound(a,kind,"1","NODE_PRODUCE"));
   for(String op:java.util.List.of("HOST_INPUT_CONSUME","HOST_PREDECESSOR_CONSUME","HOST_ENVELOPE_CONSUME")){
    a.withArray("operations").add(op);assertThrows(RuntimeException.class,()->TaskNodeProducerAuthority.requireBound(a,kind,"1",op));
   }
  }
 }
 @Test void enterpriseBudgetIsExplicitExactBasisNotProjectHistory()throws Exception{var a=author();a.remove("enterprise_budget_basis");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));a.put("enterprise_budget_basis",id(70));assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));a.set("enterprise_budget_basis",author().required("enterprise_budget_basis"));assertNotNull(schema.validate("InputAuthor",a));}
 @Test void allEightExplicitKindsAreAcceptedButNotDuplicatesOrUnknown()throws Exception{var a=author();var kinds=a.putArray("artifact_kinds");TaskNodeProducerProtocol.KINDS.stream().sorted().forEach(kinds::add);assertEquals(8,kinds.size());assertNotNull(schema.validate("InputAuthor",a));kinds.add("TASK_NODE_INPUT");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));kinds.remove(kinds.size()-1);kinds.set(0,com.fasterxml.jackson.databind.node.TextNode.valueOf("UNKNOWN"));assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));}
 @Test void supervisorPrepareReadMustBeExplicitAndNoCompletionExceptionExists()throws Exception{var a=author();assertFalse(a.required("operations").toString().contains("SUPERVISOR_PREPARE_READ"));a.withArray("operations").add("SUPERVISOR_PREPARE_READ");assertNotNull(schema.validate("InputAuthor",a));a.withArray("operations").add("HOST_COMPLETION_METADATA_CONSUME");assertThrows(RuntimeException.class,()->schema.validate("InputAuthor",a));var all=author();var operations=all.putArray("operations");TaskNodeProducerProtocol.OPERATIONS.stream().sorted().forEach(operations::add);assertEquals(6,operations.size());assertNotNull(schema.validate("InputAuthor",all));}
}
